{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "느린 조회의 원인을 실행 계획에서 찾아 인덱스 추가를 선택한 근거와 개선 효과를 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 인턴 당시 운영 화면의 신고 목록 조회에 3.2초가 걸렸다.",
          "task": "조회 지연의 원인을 찾아 적절한 개선 방법을 선택해야 했다.",
          "action": "실행 계획을 근거로 조회 조건에 맞는 인덱스를 추가하고 조인 순서를 정리했다.",
          "result": "개선 전후의 조회 시간을 비교해 3.2초에서 0.4초로 단축된 효과를 확인했다."
        },
        "expectedEvidence": [
          "실행 계획과 조회 조건을 근거로 인덱스 추가를 선택한 이유",
          "확인한 병목에 맞춰 인덱스와 조인을 수정한 내용",
          "같은 조회 조건에서 개선 전후 응답 시간을 수치로 비교한 내용"
        ]
      },
      "question": "포켓마켓 인턴으로 신고 목록 조회 시간을 3.2초에서 0.4초로 줄이셨는데요. 인덱스를 추가하기로 판단한 근거는 무엇이었나요?",
      "answerTip": "당시 직접 확인한 사실을 중심으로 구체적으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실행 계획과 조회 조건에서 확인한 병목을 인덱스 추가의 판단 근거로 구체적으로 설명한다.",
            "병목에 맞춘 인덱스와 조인 수정 내용 및 동일한 조회 조건의 개선 전후 측정값을 제시한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "실행 계획이나 조회 조건에 근거한 인덱스 선택 이유는 설명하지만 수정 내용이나 전후 측정이 불명확하다."
          ]
        },
        "poor": {
          "criteria": [
            "인덱스가 일반적으로 빠르다는 설명에 그치거나 당시 인덱스 추가를 선택한 근거를 제시하지 못한다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "중복 알림의 원인을 로그로 좁힌 근거와 복구 조치 및 재발 방지의 구분을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 인턴 당시 배포 다음 날 같은 알림이 두 번 발송된다는 문의가 들어왔다.",
          "task": "중복 발송의 원인을 추적하고 복구 조치와 재발 방지 방안을 마련해야 했다.",
          "action": "시간순 로그로 두 서버의 스케줄러 중복 실행을 찾아 잠금을 적용하고 배포 체크리스트를 보완했다.",
          "result": "중복 실행을 막는 수정의 효과를 확인하고 이후 배포에서도 점검할 장치를 마련한다."
        },
        "expectedEvidence": [
          "로그에서 두 서버의 스케줄러 중복 실행을 원인으로 좁힌 근거",
          "잠금 적용으로 중복 실행을 막은 방식과 복구 여부를 확인한 내용",
          "복구 조치와 구분해 배포 체크리스트에 재발 방지 점검을 반영한 내용"
        ]
      },
      "question": "포켓마켓 인턴 때 배포 후 알림 중복 발송 오류를 수정하셨는데요. 스케줄러 중복 실행이 원인이라고 판단한 로그상의 근거는 무엇이었나요?",
      "answerTip": "당시 상황을 떠올리며 본인이 확인한 내용을 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "시간순 로그에서 두 서버의 실행을 비교한 내용으로 중복 실행을 원인으로 좁힌 근거를 설명한다.",
            "잠금 적용과 복구 확인 내용을 제시하고, 배포 체크리스트를 통한 재발 방지를 별도로 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "중복 실행을 원인으로 판단한 로그 근거는 설명하지만 복구 확인이나 재발 방지 내용이 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "로그를 봤다는 말에 그치거나 중복 실행을 원인으로 판단한 구체적인 근거를 제시하지 못한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "인터뷰에서 수집한 요청의 목적과 우선순위를 근거로 구현 범위를 정하고 문서로 합의하는 행동을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 팀 프로젝트에서 세탁소 다섯 곳의 인터뷰로 요청을 수집한 상황이다.",
          "task": "수집한 요청을 구체적인 요구사항으로 정리하고 구현할 범위를 정해야 했다.",
          "action": "요청 목적과 우선순위로 범위를 정하고 제외 항목과 예외를 문서화해 개발 담당 팀원과 조정한다.",
          "result": "요구사항 정의서에 구현 범위가 명확히 남고 개발 담당 팀원과 합의된 상태를 확인한다."
        },
        "expectedEvidence": [
          "요청 목적과 우선순위를 근거로 구현 범위를 정한 판단",
          "제외 항목과 예외 케이스를 요구사항 정의서에 명시한 사례",
          "요구사항 정의서를 바탕으로 개발 담당 팀원과 범위를 합의한 행동"
        ]
      },
      "question": "플랜업스쿨의 동네 세탁소 예약 서비스 팀 프로젝트에서 세탁소 다섯 곳을 인터뷰하셨는데요. 구현할 요구사항의 범위는 어떤 기준으로 정하셨나요?",
      "answerTip": "한 가지 사례를 골라 당시의 판단을 구체적으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "요청 목적과 우선순위에 따른 범위 판단을 실제 포함하거나 제외한 요구사항으로 설명한다.",
            "제외 항목과 예외를 문서에 남기고 개발 담당 팀원과 범위를 합의한 행동과 결과가 확인된다."
          ]
        },
        "acceptable": {
          "criteria": [
            "요청 목적과 우선순위에 근거한 범위 판단은 확인되지만 문서화나 범위 합의 사례가 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "구현 범위를 정한 기준이 확인되지 않거나 인터뷰를 진행했다는 설명에 그친다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "기능 흐름에서 화면 상태가 달라지는 조건을 구분하고 예외와 안내 문구를 설계에 명시하는 행동을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 팀 프로젝트에서 예약 흐름을 포함한 화면설계서를 작성한 상황이다.",
          "task": "예약 흐름의 화면 상태와 전환 조건을 구현 가능한 수준으로 구체화해야 했다.",
          "action": "화면 상태가 달라지는 조건을 구분하고 화면별 예외 처리와 안내 문구를 설계서에 명시한다.",
          "result": "화면설계서만으로 상태별 화면과 예외 대응을 파악할 수 있는 수준인지 확인한다."
        },
        "expectedEvidence": [
          "예약 화면의 상태가 달라지는 조건을 구분한 기준과 사례",
          "화면별 예외 상황에서의 동작을 설계서에 명시한 사례",
          "화면 상태에 맞는 안내 문구를 설계서에 구체적으로 작성한 사례"
        ]
      },
      "question": "동네 세탁소 예약 서비스 팀 프로젝트에서 화면설계서 28장을 작성하셨는데요. 예약 화면의 상태가 바뀌는 조건은 어떤 기준으로 구분하셨나요?",
      "answerTip": "직접 작성한 내용 중 한 장면을 떠올려 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "예약 화면의 상태를 구분한 기준이 구체적인 전환 조건과 화면 사례로 확인된다.",
            "예외 상황의 동작과 상태별 안내 문구가 설계서에 어떻게 명시됐는지 구체적으로 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "화면 상태를 구분한 기준과 사례는 확인되지만 예외 동작이나 안내 문구의 구체성이 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "화면 상태를 구분한 기준이 확인되지 않거나 화면 수와 작성 도구만 설명한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "처방 용량의 이상을 알아차린 근거와 투약을 멈추고 확인하는 행동을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "푸른결종합병원에서 진통제 처방 용량이 평소의 두 배로 들어왔다.",
          "task": "처방의 적절성을 확인하기 전까지 잘못된 투약을 막아야 했다.",
          "action": "용량이 의심스러운 근거에 따라 투약을 멈추고 담당의에게 확인했다.",
          "result": "처방 입력 오류를 확인해 잘못된 용량의 투약을 예방했다."
        },
        "expectedEvidence": [
          "처방 용량을 의심해 투약을 멈춘 판단 근거를 제시한다.",
          "투약 전 환자와 약물, 용량, 경로, 시간을 확인한다.",
          "의심 처방의 수행 여부를 담당자 확인 결과에 따라 결정한다."
        ]
      },
      "question": "푸른결종합병원에서 진통제 처방 용량이 평소의 두 배로 들어온 경험이 있으셨는데요. 당시 무엇을 근거로 투약을 멈추셨나요?",
      "answerTip": "당시 상황에서 본인이 판단한 내용을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "투약 중단의 근거와 환자, 약물, 용량, 경로, 시간의 확인 행동을 구체적으로 설명한다.",
            "담당자에게 의심 처방을 확인한 내용과 그 결과에 따른 수행 여부가 구체적으로 드러난다."
          ]
        },
        "acceptable": {
          "criteria": [
            "투약을 멈춘 근거는 분명하지만, 투약 전 확인 항목이나 담당자 확인 후 판단은 구체적이지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "투약을 멈춘 판단 근거가 드러나지 않거나, 질문과 관계없는 투약 경험만 설명한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "정기 관찰에서 발견한 상태 변화를 정확히 기록하고 보고와 인수인계로 연결하는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "푸른결종합병원 정형외과 병동에서 활력징후와 통증 관찰 기록을 맡았다.",
          "task": "환자 상태 변화가 기록과 전달 과정에서 누락되지 않도록 해야 했다.",
          "action": "정기 관찰 결과의 변화를 기록하고 이상 징후를 의사와 다음 근무자에게 전달했다.",
          "result": "상태 변화와 후속 대응 내용이 기록으로 남아 다음 근무에서도 확인되었다."
        },
        "expectedEvidence": [
          "정기 관찰에서 확인한 변화의 시각과 구체적인 상태를 기록한다.",
          "발견한 이상 징후를 담당 의사에게 지체 없이 보고한다.",
          "환자 상태 변화와 후속 대응 내용을 다음 근무자에게 인계한다."
        ]
      },
      "question": "푸른결종합병원 정형외과 병동에서 활력징후와 통증 관찰 기록을 맡으셨는데요. 환자 상태 변화를 간호 기록에 남길 때 어떤 내용을 기록하셨나요?",
      "answerTip": "직접 맡았던 사례 하나를 떠올려 구체적으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "정기 관찰에서 확인한 변화의 시각과 구체적인 상태가 실제 기록 사례로 드러난다.",
            "이상 징후의 의사 보고와 다음 근무자 인계가 구체적인 전달 내용과 결과로 확인된다."
          ]
        },
        "acceptable": {
          "criteria": [
            "상태 변화에 대해 기록한 내용은 확인되지만, 의사 보고나 다음 근무자 인계는 빠지거나 모호하다."
          ]
        },
        "poor": {
          "criteria": [
            "환자 상태 변화에 대해 무엇을 기록했는지 확인되지 않거나, 질문과 무관한 업무만 설명한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P04",
  "interviews": [
    {
      "categoryId": "P04-C1",
      "itemId": "P04-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "주어진 하중이 축에 전달되는 방식을 근거로 주요 치수를 결정하고 조립 조건을 고려했는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "기계요소설계 수업 과제에서 교재의 하중 조건으로 감속기 축을 설계했다.",
